#!/usr/bin/env bash
# Exit 0: synchronized; exit 2: merge conflict requires the linked pull request.
set -euo pipefail

: "${SYNC_REPOSITORY:?Set the destination GitHub repository}"
upstream_url="${SYNC_UPSTREAM_URL:-https://github.com/gitroomhq/postiz-app.git}"
target_branch=main
source_branch=main

summary() {
  printf '%s\n' "$1"
  if [[ -n "${GITHUB_STEP_SUMMARY:-}" ]]; then
    printf '%s\n' "$1" >> "$GITHUB_STEP_SUMMARY"
  fi
}

if [[ -n "$(git status --porcelain)" ]]; then
  echo 'Refusing to synchronize a dirty checkout.' >&2
  exit 1
fi

git config user.name 'github-actions[bot]'
git config user.email '41898282+github-actions[bot]@users.noreply.github.com'
git fetch --no-tags origin "$target_branch"
git switch --detach "origin/$target_branch"

if git remote get-url upstream >/dev/null 2>&1; then
  if [[ "$(git remote get-url upstream)" != "$upstream_url" ]]; then
    echo 'The upstream remote does not match the configured source.' >&2
    exit 1
  fi
else
  git remote add upstream "$upstream_url"
fi
git fetch --no-tags upstream "$source_branch"
source_ref="refs/remotes/upstream/$source_branch"
upstream_sha="$(git rev-parse "$source_ref")"
fork_sha="$(git rev-parse HEAD)"

if git merge-base --is-ancestor "$upstream_sha" HEAD; then
  summary "Already synchronized with upstream main at $upstream_sha."
  exit 0
fi

if git merge --no-edit "$source_ref"; then
  # Ask GitHub to merge on the server: GITHUB_TOKEN cannot git-push changes
  # to workflow files. The merge API preserves concurrent commits on main too.
  gh api --method POST "repos/$SYNC_REPOSITORY/merges" \
    -f base="$target_branch" -f head="$upstream_sha" >/dev/null
  git fetch --no-tags origin "$target_branch"
  git merge-base --is-ancestor "$fork_sha" "origin/$target_branch"
  git merge-base --is-ancestor "$upstream_sha" "origin/$target_branch"
  summary "Merged upstream main ($upstream_sha) into $SYNC_REPOSITORY:$target_branch. No deployment was triggered."
  exit 0
fi

conflicts="$(git diff --name-only --diff-filter=U)"
if [[ -z "$conflicts" ]]; then
  echo 'Upstream merge failed without file conflicts; refusing to change main.' >&2
  exit 1
fi
git merge --abort

# Reference upstream directly; no workflow-file pushes or long-lived PAT needed.
# Use REST because gh pr create does not support organization-owned head forks.
pr_url="$(gh api --method GET "repos/$SYNC_REPOSITORY/pulls" \
  -f base="$target_branch" -f head="gitroomhq:$source_branch" -f state=open \
  --jq '.[0].html_url // empty')"
if [[ -z "$pr_url" ]]; then
  body_file="$(mktemp)"
  trap 'rm -f "$body_file"' EXIT
  cat > "$body_file" <<EOF
# What kind of change does this PR introduce?

Upstream synchronization for the Onpost fork. This brings gitroomhq/postiz-app main
at $upstream_sha into main. Automatic merging found conflicts, so the existing
Onpost commits and main branch have been preserved for manual resolution.

# Why was this change needed?

Keep the fork current without replacing its customizations or force-pushing main.

Conflicting paths:

\`\`\`
$conflicts
\`\`\`

# Other information:

Generated by the fork's synchronization workflow, targeting this fork only.
Merging this pull request does not deploy the running Onpost service.

# QA

1. [ ] In this fork, create a repair branch from origin/main, merge upstream/main, resolve the listed conflicts while retaining Onpost changes, and open a replacement PR from that repair branch. Do not push changes to the upstream repository.
2. [ ] Run python3 .github/scripts/test-onpost-sync-upstream.py -v and confirm the synchronization checks pass.
3. [ ] Review the upstream application changes and run the affected application checks before merging into main.

# Checklist:

- [ ] Resolve the merge conflicts and review the resulting diff.
- [ ] Complete the QA steps above before merging.
EOF
  pr_url="$(gh api --method POST "repos/$SYNC_REPOSITORY/pulls" \
    -f base="$target_branch" -f head="gitroomhq:$source_branch" -f head_repo=postiz-app \
    -f title="Sync upstream main (${upstream_sha:0:12}): resolve conflicts" \
    -F "body=@$body_file" --jq .html_url)"
fi

summary "Automatic merge stopped to preserve Onpost changes. Resolve conflicts in $pr_url"
exit 2
